19	def AscConstructor : NativeOpTrait<"AscConstructorTrait">;
20	def AscMemberFunc : NativeOpTrait<"AscMemberFuncTrait">;
21	def AscFunc : NativeOpTrait<"AscFuncTrait">;
22	
23	class AscendC_Op<string mnemonic, list<Trait> traits = []>
24	    : Op<AscendC_Dialect, mnemonic, traits> {
25	  let cppNamespace = "::mlir::ascendc";
26	  let assemblyFormat = "operands attr-dict `:` qualified(type(operands))";
27	  // `genEmitter` is a boolean flag indicating whether this operation can auto code generation
28	  // for it's emitter function. It is set to true if any of the following traits are present
29	  // - AscConstructor: The operation represents a constructor call
30	  // - AscMemberFunc: The operation represents a member function call
31	  // - AscFunc: The operation represents a regular function call
32	  // The flag defaulting to false if none of these traits are present.
33	  // When true, the operation's auto emitter function will be generated during  code emission phase
34	  bit genEmitter = !foldl(
35	    0, traits, init, trait,
36	    !or(init,
37	        !eq(trait, AscConstructor),
38	        !eq(trait, AscMemberFunc),
39	        !eq(trait, AscFunc)
40	    )
41	  );
42	  // `paramTypeLists` defines the mapping between operation arguments and parameters.
43	  // The list corresponds one-to-one with the operation's arguments, where each value specifies
44	  // how the arguments should be treated for template parameters generation:
45	  // -3: Pointer type parameter
46	  // -2: Pointer to int type parameter
47	  // -1: The argument is an attributes (not a template)
48	  //  0: Regular parameter (pass directly as a function parameter)
49	  //  1: Extract the template type from the argument at this position (e.g., <typename T> form function(T arg))
50	  //  2: Extract the element type from a template type (e.g., LocalTensor<T> -> T)
51	  //  3：Non-type template parameter (enum value)
52	  //  4: Non-type template parameter (regular value)
53	  //  5: Type template paramter (eg., <typename T> function())
54	  //  6: Type attribute as template parameter (e.g., TypeAttr for <typename T>, no function parameter)
55	  // This allows flexible template argument generation from operation arguments while supporting
56	  // various patterns like type extraction and non-type template
57	  list<int> paramTypeLists = [];
58	}
